def blocks(a,bg):
    '''find max-connected components of each color'''
    H,W=a.shape
    seen=set()
    res=[]
    for i in range(H):
        for j in range(W):
            v=a[i,j]; if v==bg or (i,j) in seen: continue
            stack=[(i,j)]; cells=[]
            while stack:
                r,c=stack.pop(); if (r,c) in seen or not(0<=r<H and 0<=c<W) or a[r,c]!=v: continue
                seen.add((r,c)); cells.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nb=(r+dr,c+dc); if nb not in seen and 0<=nb[0]<H and 0<=nb[1]<W and a[nb]==v: stack.append(nb)
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            ch=max(rs)-min(rs)+1; cw=max(cs)-min(cs)+1
            sub=a[min(rs):min(rs)+ch, min(cs):min(cs)+cw]
            res.append({'color':v,'rs':min(rs),'cs':min(cs),'ch':ch,'cw':cw,'sub':sub,'cells':set(cells)})
    return res

