def comps(g, bg):
    seen=np.zeros(g.shape,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j]!=bg and not seen[i,j]:
                stack=[(i,j)]; cells=[]
                while stack:
                    x,y=stack.pop()
                    if seen[x,y] or g[x,y]==bg: continue
                    seen[x,y]=True; cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=(x+dx,y+dy)
                        if 0<=a<g.shape[0] and 0<=b<g.shape[1] and not seen[a,b]:
                            stack.append((a,b))
                cols=set(g[x,y] for x,y in cells)
                out.append((cells,cols))
    return out
