import numpy as np
def core(g):
    g=np.array(g); bg=2 if True else None; seen=np.zeros(g.shape,bool)
    out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if (g[i,j]!=bg or g[i,j] not in {0,3,4}) and not seen[i,j]: pass
    def comps(g,bg=None):
        if bg is None: bg=g.flat[0]
        g=np.array(g); seen=np.zeros(g.shape,bool); out=[]
        for i in range(g.shape[0]):
            for j in range(g.shape[1]):
                if g[i,j]!=bg and not seen[i,j]:
                    stack=[(i,j)]; cells=[]
                    while stack:
                        x,y=stack.pop()
                        if seen[x,y] or g[x,y]==bg: continue
                        seen[x,y]=True; cells.append((x,y))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            a,b=(x+dx,y+dy)
                            if 0<=a<g.shape[0] and 0<=b<g.shape[1] and not seen[a,b]:
                                stack.append((a,b))
                    cols=set(g[x,y] for x,y in cells)
                    if len(cols)>=2: out.append((cells,sorted(cols)))
