    # normalized bitmask of shape (relative coords)
    ys=[m[0] for m in cset]; xs=[m[1] for m in cset]
    cy=min(ys); cx=min(xs)
    s=0
    for m in cset: s |= (1 << (m[0]-cy)) | ((1<<(m[1]-cx))<<len(xs))
    # compact column offsets
    cols=sorted({m[1] for m in cset}); colmap={c:i for i,c in enumerate(cols)}
    vals=sorted({m[0] for m in cset})
    # encode as list of (row,col) relative to min
