    base=Counter(pts)
    cols2=sorted(base.keys())
    rows2=sorted(set(m[0] for m in pts))
    pts2=[(m[0]-min(rows2),m[1]-min(cols2)) for m in pts]
    # canonicalize by minimal rotation sequence
    def key(p):
        p=[(r%3,c%3) for r,c in p]
        seq=[tuple(sorted(p))]
        return hash(tuple(sorted(p)))
    return tuple(sorted((r,c) for r,c in pts2))

