def f(inp):
    g=np.array(inp); H,W=g.shape
    cnt=Counter(g.flatten().tolist())
    bg=cnt.most_common(1)[0][0]
    # find marker color: color appearing on exactly 4 cells, 2 in two rows and 2 in two cols? 
    # find rows that have exactly 2 distinct colors -> skip. Look for color with exactly 2 rows of single occurrences each spanning >=2 cells
    # Find horizontal lines: a color where count of cells in single rows is 2 each (marker rows)
    marker_c=None
    for c in sorted(cnt):
        if c==bg: continue
        rows_of=[r for r in range(H) if g[r].count(c)>=2]
        cols_of=[]
        for cc in range(W):
            cols_count=sum(1 for r in range(H) if g[r,cc]==c)
            if cols_count>=2:
                cols_of.append(cc)
        if len(rows_of)==2 and len(cols_of)==2:
            marker_c=c
            break
    if marker_c is None:
        # fallback: color with count 4 exactly, in corners
        for c in sorted(cnt):
            if c!=bg and cnt[c]==4:
                marker_c=c; break
    ys=[r for r in range(H) if sum(g[r]==marker_c)>=2]
    xs=[c for c in range(W) if sum(g[:,c]==marker_c)>=2]
    assert len(ys)==2 and len(xs)==2
    r1,r2=sorted(ys); c1,c2=sorted(xs)
    oh,ow=r2-r1+1, c2-c1+1
    out=np.full((oh,ow),bg)
    for r in range(H):
        for cc in range(W):
            v=int(g[r,cc])
            if v==marker_c: continue
            if v!=bg and r>r1 and r<r2 and c1<=cc<=c2:
                yr=r-r1; xc=cc-c1
                out[yr,xc]=v
    return out.tolist(),marker_c,(r1,r2,c1,c2)

