import numpy as np
def comps(grid):
    g=np.array(grid)
    oh,ow=g.shape
    seen=set(); out=[]
    for r in range(oh):
        for c in range(ow):
            if (r,c) in seen or g[r,c]==2: continue
            col=g[r,c]; stack=[(r,c)]; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<oh and 0<=nx<ow and (ny,nx) not in seen and g[ny,nx]==col:
                        seen.add((ny,nx)); stack.append((ny,nx))
            out.append((len(cells),col,sorted(cells)))
    return out

