def comps_info(g):
    info={}
    g=np.array(g)
    oh,ow=g.shape; seen=set()
    for r in range(oh):
        for c in range(ow):
            if (r,c) in seen or g[r,c]==2: continue
            col=int(g[r,c]); stack=[(r,c)]; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<oh and 0<=nx<ow and (ny,nx) not in seen and g[ny,nx]==col:
                        seen.add((ny,nx)); stack.append((ny,nx))
            info.setdefault(col,[]).append((len(cells),sorted(cells)))
    return info

